int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    ssh_kex_t *kex = ssh_session_get_kex(ctxt);
    int rc;

    if (!kex) {
        return SSH_ERROR_INVALID_KEX;
    }

    dispatch_set(SSH_MSG_KEXINIT, kex_init_dispatch, ctxt);
    rc = ssh_packet_read(ctxt);
    if (rc != SSH_OK) {
        return rc;
    }

    ssh_buffer_consume(ssh_packet_get_buffer(), 4); /* Skip sequence number */

    if (kex->first_kex_follows) {
        if (!kex->sent_kex_init) {
            rc = kex_send_init(ctxt);
            if (rc != SSH_OK) {
                return rc;
            }
            kex->sent_kex_init = 1;
        }
    }

    rc = kex->kex_methods->kex(kex);
    if (rc != SSH_OK) {
        return rc;
    }

    return SSH_OK;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    SSH_SESSION *session = (SSH_SESSION *)ctxt;
    if (!session || !session->kex) {
        return SSH_ERR_INTERNAL_ERROR;
    }

    if (dispatch_set((dispatch_t *)session->dispatch, SSH_MSG_KEXINIT, handle_kex_init)) {
        return SSH_ERR_INTERNAL_ERROR;
    }

    PACKET *pkt = packet_read();
    if (!pkt) {
        return SSH_ERR_MESSAGE_RECV_FAILED;
    }

    /* Discard unnecessary data from the packet */
    packet_get_string(pkt, NULL, 0);
    packet_get_end(pkt);

    /* Check if key exchange initialization was already sent */
    if (!session->kex->kexinit_sent) {
        kexinit_send(session);
        session->kex->kexinit_sent = 1;
    }

    /* Select and execute the appropriate key exchange method */
    int ret = kex_choose_and_execute(session);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    SSH_SESSION *session = (SSH_SESSION *)ctxt;
    PACKET *packet = session->in_packet;

    if (!session || !packet || !session->kex) {
        return KEX_ERROR_INVALID_STATE;
    }

    dispatch_set((void *)kex_init_dispatch, session);

    if (packet_get_end(packet) != packet_get_length(packet)) {
        packet_discard(packet);
    }

    if (session->kex->first_kex_follows) {
        if (!session->kex->sent_kex_init) {
            kex_send_init(session);
            session->kex->sent_kex_init = 1;
        }
    }

    return select_and_run_kex_method(session);
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    struct ssh *ssh = ctxt;
    struct kex *kex = ssh->kex;

    if (kex == NULL)
        return SSH_ERR_NO_KEX;

    if (ssh->kex_state & KEX_INIT_DONE)
        return SSH_ERR_KEXINIT_ALREADY_SENT;

    ssh->kex_state |= KEX_INIT_SENT;

    if (packet_get_protocol_version(ssh) != SSH_PROTOCOL_VERSION)
        return SSH_ERR_KEX_FAILURE;

    kex->first_kex_follows = packet_get_char();
    kex->kex_follows = kex->first_kex_follows;

    if (kex->first_kex_follows)
        kex->kex_state = KEX_DH_GRP1;

    return kex->kex_func(kex);
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    ssh_session *session = ctxt;
    if (!session || !session->kex) {
        return SSH_ERR_INVALID_ARGUMENT;
    }

    if (ssh_dispatch_run(SSH_MSG_KEX_INIT, session) != 0) {
        return SSH_ERR_DISPATCH;
    }

    if (packet_get_int() != 0) {
        return SSH_ERR_PROTO;
    }

    if (!session->kex->first_kex_follows) {
        if (kex_send_init(session) != 0) {
            return SSH_ERR_KEY_EXCHANGE_FAILURE;
        }
    }

    if (kex_choose_methods(session) != 0) {
        return SSH_ERR_KEY_EXCHANGE_FAILURE;
    }

    return 0;
}
